19	// historyLegacyIdentity is a complete strong identity derived from one fully
20	// read and parsed legacy index. Observed* binds a later best-effort manifest
21	// update to the exact source generation the caller used.
22	type historyLegacyIdentity struct {
23		ObservedGeneratedAt time.Time
24		ObservedIndexPath   string
25		ObservedRecords     int
26		IndexBytes          int64
27		IndexSHA256         string
28		RecordsFingerprint  string
29	}
30	
31	func historySourceNeedsIdentityUpgrade(source *historySourceManifest) bool {
32		return source != nil && (source.IndexBytes == 0 || source.IndexSHA256 == "" || source.RecordsFingerprint == "")
33	}
34	
35	// deriveHistoryLegacyIdentity accepts only a complete, internally consistent
36	// legacy generation. Existing non-empty fields remain authoritative: a partial
37	// migration with a conflicting field is not repaired opportunistically.
38	func deriveHistoryLegacyIdentity(source *historySourceManifest, data []byte, index historyIndex) *historyLegacyIdentity {
39		if !historySourceNeedsIdentityUpgrade(source) || source.IndexPath == "" || source.GeneratedAt.IsZero() ||
40			source.Records < 0 || len(index.Records) != source.Records || !index.GeneratedAt.Equal(source.GeneratedAt) {
41			return nil
42		}
43		identity := &historyLegacyIdentity{
44			ObservedGeneratedAt: source.GeneratedAt,
45			ObservedIndexPath:   source.IndexPath,
46			ObservedRecords:     source.Records,
47			IndexBytes:          int64(len(data)),
48			IndexSHA256:         historyIndexBytesFingerprint(data),
49			RecordsFingerprint:  historyRecordsFingerprint(index.Records),
50		}
51		if source.IndexBytes != 0 && source.IndexBytes != identity.IndexBytes {
52			return nil
53		}
54		if source.IndexSHA256 != "" && source.IndexSHA256 != identity.IndexSHA256 {
55			return nil
56		}
57		if source.RecordsFingerprint != "" && source.RecordsFingerprint != identity.RecordsFingerprint {
58			return nil
59		}
60		return identity
61	}
62	
63	func (identity *historyLegacyIdentity) sourceWithIdentity(source *historySourceManifest) *historySourceManifest {
64		if identity == nil || source == nil {
65			return source
66		}
67		upgraded := *source
68		upgraded.IndexBytes = identity.IndexBytes
69		upgraded.IndexSHA256 = identity.IndexSHA256
70		upgraded.RecordsFingerprint = identity.RecordsFingerprint
71		return &upgraded
72	}
