74	// rankHistoryViaLegacyDirectPayload is deliberately scoped to a legacy manifest
75	// paired with an already-present schema-v2 FTS cache. It validates the cache's
76	// identity metadata and hydrated row structure against identity derived from
77	// index truth under the existing cooperative local-cache trust model; it does
78	// not prove byte-for-byte payload equality. Schema-v1 caches remain ordinary
79	// misses and are not migrated here. Migration failure is ignored: the result
80	// remains usable and a later invocation can retry.
81	func rankHistoryViaLegacyDirectPayload(brainDir string, source *historySourceManifest, identity *historyLegacyIdentity, kind, query string, limit int, cutoff float64) ([]scoredHistoryRecord, bool) {
82		if identity == nil {
