84		}
85		upgraded := identity.sourceWithIdentity(source)
86		scored, used, err := rankHistoryViaFreshFTSCutoffDetailed(brainDir, upgraded, kind, query, limit, cutoff)
87		if err != nil || !used {
88			return nil, false
89		}
90		_ = persistHistoryLegacyIdentity(brainDir, identity)
91		return scored, true
92	}
