94	// persistHistoryLegacyIdentity fills only absent identity fields. It takes the
95	// existing writer lock without waiting, reloads the manifest to preserve any
96	// concurrent changes, and re-reads the authoritative file under that lock. The
97	// second byte identity check closes the read-to-lock replacement window.
98	func persistHistoryLegacyIdentity(brainDir string, identity *historyLegacyIdentity) error {
99		if identity == nil {
100			return nil
101		}
102		unlock, err := brainstore.AcquireBrainWriteLockTimeout(brainDir, 0)
103		if err != nil {
104			return err
105		}
106		defer unlock()
107	
108		// Strict: this migration rewrites the manifest from this struct further
109		// down, so a field this build cannot name must stop it rather than be
110		// dropped on the way through.
111		manifest, err := bmanifest.LoadForReplace(brainDir)
