113			return err
114		}
115		if manifest.Sources == nil || manifest.Sources.History == nil {
116			return errors.New("history source changed before identity migration")
117		}
118		current := manifest.Sources.History
119		if current.IndexPath != identity.ObservedIndexPath || current.Records != identity.ObservedRecords ||
120			!current.GeneratedAt.Equal(identity.ObservedGeneratedAt) {
121			return errors.New("history source generation changed before identity migration")
122		}
123		if err := historyIdentityFieldsCompatible(current, identity); err != nil {
124			return err
125		}
126		fingerprint, err := historyIndexFingerprintForIdentityRecheck(brainDir, current.IndexPath, identity.IndexBytes)
127		if err != nil {
128			return err
129		}
130		if fingerprint != identity.IndexSHA256 {
131			return errors.New("history index changed before identity migration")
132		}
133	
134		changed := false
135		if current.IndexBytes == 0 {
136			current.IndexBytes = identity.IndexBytes
137			changed = true
138		}
139		if current.IndexSHA256 == "" {
140			current.IndexSHA256 = identity.IndexSHA256
141			changed = true
142		}
143		if current.RecordsFingerprint == "" {
144			current.RecordsFingerprint = identity.RecordsFingerprint
145			changed = true
146		}
147		if !changed {
148			return nil
149		}
