153	func historyIdentityFieldsCompatible(source *historySourceManifest, identity *historyLegacyIdentity) error {
154		if source.IndexBytes != 0 && source.IndexBytes != identity.IndexBytes {
155			return errors.New("history index size identity changed before migration")
156		}
157		if source.IndexSHA256 != "" && source.IndexSHA256 != identity.IndexSHA256 {
158			return errors.New("history index checksum identity changed before migration")
159		}
160		if source.RecordsFingerprint != "" && source.RecordsFingerprint != identity.RecordsFingerprint {
161			return errors.New("history records identity changed before migration")
162		}
163		return nil
164	}
