166	func historyIndexFingerprintForIdentityRecheck(brainDir, indexPath string, expectedBytes int64) (string, error) {
167		if expectedBytes <= 0 {
168			return "", errors.New("history index identity has invalid size")
169		}
170		clean, err := validateHistoryIndexPath(indexPath)
171		if err != nil {
172			return "", err
173		}
174		if err := rejectSymlinkPathComponents(brainDir, clean); err != nil {
175			return "", err
176		}
177		path := filepath.Join(brainDir, clean)
178		if err := base.RejectUnsafeExistingRegularFile(path, "history index"); err != nil {
179			return "", historyHardlinkRepairHint(err)
180		}
181		f, err := os.OpenFile(path, os.O_RDONLY|base.FileLockOpenFlags(), 0)
182		if err != nil {
183			return "", err
184		}
185		defer f.Close()
186		if err := base.RejectOpenFileAlias(path, f, "history index"); err != nil {
187			return "", historyHardlinkRepairHint(err)
188		}
189		before, err := f.Stat()
190		if err != nil {
191			return "", err
192		}
193		if before.Size() != expectedBytes {
194			return "", fmt.Errorf("history index size changed before identity migration: got %d, want %d", before.Size(), expectedBytes)
195		}
196	
197		h := sha256.New()
198		n, err := io.CopyN(h, f, expectedBytes)
199		if err != nil {
200			return "", fmt.Errorf("read history index identity: copied %d of %d bytes: %w", n, expectedBytes, err)
201		}
202		var extra [1]byte
203		if n, err := f.Read(extra[:]); err != io.EOF {
204			if err != nil {
205				return "", fmt.Errorf("read history index identity tail: %w", err)
206			}
207			if n > 0 {
208				return "", errors.New("history index grew before identity migration")
209			}
210		}
211		after, err := f.Stat()
212		if err != nil {
213			return "", err
214		}
215		if after.Size() != before.Size() || !after.ModTime().Equal(before.ModTime()) {
216			return "", errors.New("history index changed while verifying identity")
217		}
218		if err := base.RejectOpenFileAlias(path, f, "history index"); err != nil {
219			return "", historyHardlinkRepairHint(err)
220		}
221		return "sha256:" + hex.EncodeToString(h.Sum(nil)), nil
222	}
