224	// Identity migration does not alter the human README, generation time, or any
225	// other source. The manifest replacement itself is atomic and private.
226	func writeHistoryIdentityManifestAtomic(brainDir string, manifest exportManifest) error {
227		data, err := json.MarshalIndent(manifest, "", "  ")
228		if err != nil {
229			return fmt.Errorf("encode %s: %w", bmanifest.FileName, err)
230		}
231		data = append(data, '\n')
232		if err := brainstore.WriteBrainRelativeFileAtomic(brainDir, bmanifest.FileName, data, 0o600); err != nil {
233			return fmt.Errorf("write %s: %w", bmanifest.FileName, err)
234		}
235		return nil
236	}
