	parts := strings.Split(rel, "/")
	if len(parts) != 4 || parts[0] != brainstore.HistoryDirName || parts[1] != "generations" || parts[3] != fileName || len(parts[2]) != 40 {
		return false
	}
	_, err := hex.DecodeString(parts[2])
	return err == nil
}

